  window.LESSONS["u1_l10"] = {"meta":{"grade":5,"subject":"과학","term":2,"unit":1,"unit_title":"혼합물의 분리","n":10,"covers":"10·11차시","title":"과학이 톡톡 새활용 · 혼합물의 분리 마무리하기","goal":"🎨 새활용의 뜻과 가치를 말해요. / 🗺️ 단원에서 배운 분리 방법을 한눈에 정리해요. / ✅ 배운 내용을 스스로 평가해요.","std":"[6과05-01][6과05-02][6과05-03]","duration_min":80,"lesson_format":"새활용 탐색 + 단원 마무리 · 2세대 19장(7요소)","theme":"혼합물 분리 연구소","source":"2022 개정 과학 5-2 지도서 1단원(자기주도 원문 없음 — 케이티처 정본)","src_key":"u1_l10"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"버림에서 쓰임으로! 새활용\n혼합물의 분리 단원 마무리 (2차시)","emoji":"🏁"},"suggested_extras":["v_l8_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 혼합물의 분리를 이용한 장치를 **포스터**로 만들어 공유했어요. 오늘은 새활용을 알아보고 단원 전체를 정리해요.","items":[{"q":"포스터에서 꼭 강조할 것은?","a":"어떤 방법으로 혼합물을 분리하는지"},{"q":"포스터 만들기 세 단계는?","a":"계획하기 → 해 보기 → 나누기"},{"q":"댓글을 쓸 때 지킬 점은?","a":"바르고 고운 말 · 새로 알게 된 점 · 개인 정보 쓰지 않기"}],"from":"u1_l08"},"suggested_extras":["q_l8_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"페트병 뚜껑 벽화","desc":"커다란 벽화가 전부 **페트병 뚜껑**으로 만들어졌어요.","question":"버려질 물건을 **나누어 모아** 새 작품으로 만드는 것을 무엇이라고 할까요? 재활용과는 무엇이 다를까요?","img":"assets/photo/science/bottle_cap_mural.jpg","tnote":{"ask":["뚜껑을 어떻게 나눠 모았을까요?","이 작품이 쓰레기와 다른 점은?"],"watch":"「그냥 재활용」으로 묶는 경우 — 아이디어·디자인을 더했는지로","min":4}},"suggested_extras":["q_l8_2","r_l8_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"chain","items":[{"emoji":"🗑️","name":"버려지는 물건","kind":"안 쓰는 것"},{"emoji":"💡","name":"아이디어","kind":"상상과 쓰임 더하기"},{"emoji":"🎁","name":"새 가치","kind":"새 물건으로 태어나요"}]},"title":"새활용이란?","content":"**새활용**은 버려지는 물건에 아이디어나 디자인을 더해 **새로운 가치**를 만드는 거예요. 재활용보다 에너지와 자원을 덜 써요.","tnote":{"ask":["재활용과 새활용은 무엇이 다를까요?","새활용이 에너지를 덜 쓰는 까닭은?"],"watch":"「낡은 걸 그대로 쓰기」로 이해하는 경우","min":5}},"suggested_extras":["e_l8_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"emoji":"🏺","name":"안 쓰는 천","kind":"→ 꽃병"},{"emoji":"💡","name":"플라스틱 병","kind":"→ 물방울 조명"},{"emoji":"👜","name":"헌 옷","kind":"→ 가방"},{"emoji":"🖼️","name":"페트병 뚜껑","kind":"→ 벽화"}]},"title":"새활용 작품","content":"다시 쓸 수 있는 자원을 **나누어 모으고** 새로운 쓰임을 이어 **버림에서 쓰임**으로 바꿔요.","tnote":{"ask":["가장 마음에 드는 작품과 까닭은?","나만의 새활용 작품을 만든다면?"],"watch":"재료를 나누어 모으는 단계를 건너뛰는 경우","min":4}},"suggested_extras":["t_l8_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"emoji":"🪨","name":"모래·자갈","kind":"크기 차이 → 체"},{"emoji":"🛢️","name":"물·기름","kind":"스포이트·흡착포"},{"emoji":"🧂","name":"소금·모래","kind":"거름 → 증발"},{"emoji":"🏭","name":"생활 장치","kind":"담수화·정수 등"}]},"title":"혼합물의 분리 한눈에","content":"혼합물은 섞인 물질의 **서로 다른 성질**을 이용해 나눠요.","tnote":{"ask":["네 줄에서 이용한 성질을 하나씩 말해 볼까요?","같은 성질을 쓰는 생활 속 예는?"],"watch":"도구 이름만 말하고 성질을 빠뜨리는 경우","min":5}},"suggested_extras":["e_l8_2","t_l8_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"bins","bins":[{"name":"크기·층으로 나눠요","emoji":"📏","tone":"t0","items":[{"emoji":"🥣","name":"체 — 크기 차이"},{"emoji":"🧪","name":"스포이트·흡착포 — 위에 뜸"}],"hint":"체·떠내기"},{"name":"물에 녹는지로 나눠요","emoji":"💧","tone":"t1","items":[{"emoji":"📄","name":"거름 — 녹지 않는 것"},{"emoji":"♨️","name":"증발 — 녹아 있던 것"}],"hint":"거름 → 증발"}]},"title":"이 성질엔 이 방법","content":"어떤 혼합물인지 먼저 보고, **이용할 성질**을 골라 **알맞은 방법**을 정해요.","tnote":{"ask":["소금과 좁쌀이 섞이면 어느 칸의 방법을 쓸까요?","성질을 먼저 찾는 까닭은?"],"watch":"도구부터 고르는 경우 — 성질 먼저","min":4}},"suggested_extras":["q_l8_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각, 맞을까요?","label":"자주 하는 생각","wrong":"재활용과 새활용은 같은 말이다","right":"**재활용**은 쓴 물건이나 재료를 녹이거나 부수어 **변형**해 다시 쓰는 것이고, **새활용**은 버려지는 물건에 **아이디어·디자인을 더해** 새 가치를 만드는 거예요. 새활용은 에너지와 자원을 더 아껴요.","hint":"페트병을 녹여 옷감을 만드는 것(재활용)과 페트병 그대로 조명을 만드는 것(새활용)을 나란히 보여 주세요.","tnote":{"ask":["페트병을 녹이는 것은 어느 쪽일까요?","페트병 모양을 살려 조명을 만들면?"],"watch":"「둘 다 다시 쓰니 같다」에서 멈추는 경우","min":3}},"suggested_extras":["x_l8_1","x_l8_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🗺️","body":"배운 내용을 확인해요."},"question":"물과 기름처럼 섞이지 않는 액체 혼합물을 나눌 때 쓰는 도구는 무엇일까요?","options":[{"text":"스포이트","correct":true},{"text":"체"},{"text":"증발 접시"},{"text":"돋보기"}],"note":"풀이: 위층의 기름을 스포이트로 뽑아 옮겨요. → **스포이트**"},"suggested_extras":["t_l8_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"💬","body":"혼합물에 관한 친구들의 말을 들었어요."},"question":"혼합물에 대해 옳게 말한 것을 모두 고르세요.","options":[{"text":"모래와 자갈은 알갱이의 크기 차이로 나눌 수 있어","correct":true},{"text":"혼합물 속 물질은 성질이 변하지 않은 채 섞여 있어","correct":true},{"text":"물과 기름은 골고루 잘 섞여"},{"text":"소금물을 증발시키면 소금을 얻을 수 있어","correct":true}],"multi":true,"note":"풀이: 물과 기름은 골고루 섞이지 않아요. → 알맞은 것 **3개**"},"suggested_extras":["e_l8_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🍚","body":"좁쌀이 담긴 그릇에 소금을 떨어뜨렸어요."},"question":"좁쌀만 얻는 방법으로 알맞은 것은 무엇일까요?","options":[{"text":"물에 넣어 소금을 녹인 뒤 체로 거른다","correct":true},{"text":"그대로 증발 접시에 넣고 가열한다"},{"text":"흡착포를 올려놓는다"},{"text":"자석을 가까이 한다"}],"note":"풀이: 소금은 물에 녹아 체를 빠져나가고 좁쌀은 체에 남아요. → **물에 넣어 소금을 녹인 뒤 체로 거른다**"},"suggested_extras":["q_l8_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"소금과 모래의 혼합물에서 모래를 나누는 장치는 무엇인가요?","a":"거름 장치","steps":["소금과 모래를 물에 넣는다","녹지 않는 모래를 걸러야 한다","거름 장치라고 답한다"]},"도전":{"q":"혼합물을 분리하는 까닭으로 「우리 주변의 물질은 모두 혼합물이기 때문이다」가 옳지 않은 까닭을 말해 봐요.","a":"주변 물질에는 한 가지 물질로 이루어진 것도 있다 — 필요한 물질을 얻으려고 분리한다","steps":["1차시 말판의 한 가지 물질을 떠올린다","「모두」가 틀린 말이다","바른 까닭으로 고쳐 쓴다"]},"심화":{"q":"쓰고 남은 물건으로 나만의 새활용 작품을 계획하고, 재료를 어떻게 나누어 모을지까지 말해 봐요.","a":"여러 답 (예: 색깔별로 나눈 페트병 뚜껑으로 반 이름 모자이크 — 뚜껑을 씻어 색깔별로 모은다)","open":true}},"tnote":{"ask":["기본에서 「녹지 않는 것을 거른다」가 나왔나요?","도전에서 1차시 내용을 근거로 들었나요?"],"watch":"심화에서 나누어 모으는 단계가 빠진 경우","min":5}},"suggested_extras":["q_l8_5","g_l8_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"새활용 계획 · 단원 정리판","type":"group","goal":"모둠별로 새활용 작품 계획을 한 장 그리고, 「혼합물 → 이용한 성질 → 분리 방법 → 생활 속 예」 단원 정리판을 완성해 스스로 평가하기","steps":["쓰고 남은 물건 하나를 골라 새활용 작품과 그 까닭을 쓴다","단원 정리판 네 줄(모래·자갈 / 물·기름 / 소금·모래 / 장치)을 붙임딱지로 채운다","실험관찰 18~19쪽 문제를 풀고 서로 답을 견준다","성취기준 세 가지를 스스로 평가해 색칠한다"],"solo":["새활용 작품 계획을 그림과 한 문장으로 쓴다","정리판 네 줄을 공책에 채우고 스스로 평가한다"],"materials":["붙임딱지(과학 119쪽)","실험관찰 18~19쪽","정리판 활동지","색연필"],"minutes":25,"tnote":{"ask":["정리판마다 「이용한 성질」이 들어갔나요?","스스로 평가에서 가장 자신 없는 것은?"],"watch":"정답 맞히기에만 몰두해 새활용 계획을 건너뛰는 경우","min":25}},"suggested_extras":["g_l8_2","t_l8_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"업사이클링 아티스트","scenario":{"icon":"🧑‍🎨","body":"**업사이클링 아티스트**는 누군가 버린 물건을 미술관에서 감상할 작품으로 바꾸는 일을 해요. 버려진 물건에서 쓸 만한 것을 **나누어 골라** 새 쓰임을 찾고, 작품으로 환경과 소비에 대한 메시지를 전하기도 해요."},"content":"나누어 고르고 **새 가치**를 더하면 버림이 쓰임이 돼요."},"suggested_extras":["r_l8_2","r_l8_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"소금·모래·좁쌀이 섞여 있는 혼합물을 물에 넣었어요.","challenge":"세 가지를 모두 나누는 방법을 이 단원에서 배운 방법만으로 차례대로 말해 봐요.","note":"풀이: 물에 넣으면 소금은 녹아요. 좁쌀보다 작고 모래보다 큰 눈의 **체**로 거르면 좁쌀이 남아요. 빠져나간 모래와 소금물을 **거름 장치**로 걸러 모래를 얻고, 소금물을 **증발**시켜 소금을 얻어요.","tnote":{"ask":["크기로 먼저 나눌 수 있는 것은?","물에 녹는 것은?"],"watch":"증발을 맨 처음에 하는 경우 — 모래·좁쌀은 남는다는 점 짚기","min":4}},"suggested_extras":["t_l8_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"새활용이란 무엇인가요?","a":"버려지는 물건에 아이디어·디자인을 더해 새로운 가치를 만드는 것"},{"q":"모래와 자갈은 어떤 성질로 나누나요?","a":"알갱이의 크기 차이"},{"q":"소금과 모래의 혼합물을 나누는 두 장치는?","a":"거름 장치 · 증발 장치"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["혼합물은 섞인 물질의 **서로 다른 성질**(크기·섞이지 않음·물에 녹음)을 이용해 나눠요.","**새활용**은 나누어 모은 자원에 상상을 더해 **버림을 쓰임**으로 바꿔요.","나누는 법을 알면 버릴 것도 보물이 돼요."],"arrows":["크기 — 체 · 섞이지 않음 — 스포이트·흡착포","물에 녹음 — 거름 → 증발","생활 — 분리 장치 · 새활용"]},"suggested_extras":["r_l8_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 혼합물을 성질에 맞는 방법으로 나누는 법을 설명할 수 있나요?","🔧 과정·기능 — 배운 내용을 정리판과 문제로 스스로 확인할 수 있나요?","💛 가치·태도 — 새활용과 혼합물 분리가 생활과 가깝다고 느꼈나요?"],"prompts":["「혼합물의 분리」를 공부하고 새로 알게 된 것을 한 문장으로 써 봐요."]},"suggested_extras":["e_l8_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"이 단원을 마쳐요","preview":"다음 단원 「날씨와 우리 생활」에서는 날마다 달라지는 날씨와 우리 생활을 알아봐요.","emoji":"🌦️"},"suggested_extras":["c_l8_1"]}],"extras":[{"id":"v_l8_1","type":"video","icon":"🎥","title":"새활용 작품 영상","url":"https://www.youtube.com/results?search_query=%EC%97%85%EC%82%AC%EC%9D%B4%ED%81%B4%EB%A7%81+%ED%8E%98%ED%8A%B8%EB%B3%91+%EB%9A%9C%EA%BB%91+%EB%B2%BD%ED%99%94","description":"버려진 물건으로 만든 작품을 소개하는 장면.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l8_1","type":"fun_question","icon":"💡","title":"재활용 vs 새활용","content":"둘은 무엇이 다를까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_2","type":"fun_question","icon":"💡","title":"뚜껑 벽화","content":"뚜껑을 어떻게 나눠 모았을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_3","type":"fun_question","icon":"💡","title":"성질 먼저","content":"도구보다 성질을 먼저 찾는 까닭은?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_4","type":"fun_question","icon":"💡","title":"소금과 좁쌀","content":"소금과 좁쌀이 섞이면 어떻게 나눌까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_5","type":"fun_question","icon":"💡","title":"나만의 작품","content":"나는 무엇을 새활용하고 싶나요?","fit_slides":["concept","basic_problem"]},{"id":"t_l8_1","type":"tip","icon":"🧩","title":"스스로 먼저","content":"학생이 먼저 정리판을 채우고 수업을 이어 가요(지도서).","fit_slides":["concept","misconception"]},{"id":"t_l8_2","type":"tip","icon":"🧩","title":"세 학습 요소","content":"고체·액체 혼합물 · 거름과 증발 · 분리 장치 세 갈래로 묶어요.","fit_slides":["concept","misconception"]},{"id":"t_l8_3","type":"tip","icon":"🧩","title":"진로 이야기","content":"업사이클링 아티스트를 소개해요.","fit_slides":["concept","misconception"]},{"id":"t_l8_4","type":"tip","icon":"🧩","title":"평가 자료","content":"학업 성취도·서술형·단원 평가를 함께 써요.","fit_slides":["concept","misconception"]},{"id":"t_l8_5","type":"tip","icon":"🧩","title":"다음 단원","content":"다음 단원 준비물을 미리 안내해요.","fit_slides":["concept","misconception"]},{"id":"r_l8_1","type":"real_world","icon":"🌍","title":"업사이클 센터","content":"자원회수시설을 새활용 전시관으로 바꿨어요.","fit_slides":["real_world","summary"]},{"id":"r_l8_2","type":"real_world","icon":"🌍","title":"천 꽃병","content":"안 쓰는 천으로 꽃병을 만들어요.","fit_slides":["real_world","summary"]},{"id":"r_l8_3","type":"real_world","icon":"🌍","title":"청바지 가방","content":"입지 않는 옷으로 가방을 만들어요.","fit_slides":["real_world","summary"]},{"id":"g_l8_1","type":"game","icon":"🎮","title":"놀이로 마무리","content":"단원 말판 놀이로 배운 것을 확인해요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l8_2","type":"game","icon":"🎮","title":"성질 짝짓기","content":"혼합물 카드와 이용할 성질 카드를 짝지어요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l8_1","type":"misconception","icon":"⚠️","title":"같은 말","content":"재활용과 새활용이 같다고 여기는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"x_l8_2","type":"misconception","icon":"⚠️","title":"모두 혼합물","content":"주변 물질이 모두 혼합물이라고 여기는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"e_l8_1","type":"example","icon":"📝","title":"단원 정리판","content":"네 줄 정리판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l8_2","type":"example","icon":"📝","title":"새활용 작품","content":"꽃병·조명·가방·벽화 사진을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l8_3","type":"example","icon":"📝","title":"성취기준 셋","content":"스스로 평가 세 칸을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l8_1","type":"checklist","icon":"✅","title":"다음 단원 준비","content":"단원 평가지 · 다음 단원 교과서.","fit_slides":["next_lesson"]}]};
